// Project API calls avoid CLI account-login dependencies. Never log credentials or API bodies.
const token=process.env.VERCEL_TOKEN,project=process.env.VERCEL_PROJECT_ID,team=process.env.VERCEL_ORG_ID;
if(!token||!project||!team)throw Error('Vercel deployment credentials are missing.');
const api=async(path,method='GET',body)=>{const url=new URL('https://api.vercel.com'+path);url.searchParams.set('teamId',team);const response=await fetch(url,{method,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(60000)});const result=await response.json().catch(()=>({}));if(!response.ok){const hint=response.status===401||response.status===403?'Check that VERCEL_TOKEN is a Vercel access token authorized for this project/team.':'';throw Error(`Vercel ${method} ${url.pathname} failed (${response.status}). ${hint}`)}return result};
async function main(){
const metadata=await api('/v9/projects/'+project);if(metadata.id!==project)throw Error('Vercel project identity mismatch.');console.log('Verified Vercel project: '+metadata.name);
// Remove the unused paid-provider runtime key. Never read or log its value.
const configured=await api('/v10/projects/'+project+'/env');for(const item of configured.envs||[]){if(['OPENAI_API_KEY','OPENAI_MODEL'].includes(item.key)&&item.target?.includes('production'))await api('/v9/projects/'+project+'/env/'+item.id,'DELETE')}
if(process.env.GEMINI_API_KEY){await api('/v10/projects/'+project+'/env?upsert=true','POST',{key:'GEMINI_API_KEY',value:process.env.GEMINI_API_KEY,type:'sensitive',target:['production']});console.log('Optional Gemini key configured securely.');}
// Optional live job-posting source for Project recommendations. Without keys, Greenhouse/Lever boards and the built-in baseline are used.
for(const key of ['ADZUNA_APP_ID','ADZUNA_APP_KEY']){if(process.env[key]){await api('/v10/projects/'+project+'/env?upsert=true','POST',{key,value:process.env[key],type:'sensitive',target:['production']});console.log('Optional '+key+' configured securely.')}}
const confirmed=String(process.env.GEMINI_FREE_TIER_CONFIRMED||'').trim().replace(/^[\"']|[\"']$/g,'').toLowerCase()==='true';await api('/v10/projects/'+project+'/env?upsert=true','POST',{key:'GEMINI_FREE_TIER_CONFIRMED',value:String(confirmed),type:'plain',target:['production']});console.log(confirmed?'Owner confirmed an unbilled Free Tier project.':'Free local review active; external AI disabled until Free Tier is confirmed.');

const deployment=await api('/v13/deployments','POST',{name:metadata.name,project,target:'production',gitSource:{type:'github',repoId:Number(process.env.GITHUB_REPOSITORY_ID),ref:process.env.GITHUB_SHA}});console.log('Production deployment requested.');
for(let i=0;i<60;i++){const state=await api('/v13/deployments/'+deployment.id);if(state.readyState==='READY'){console.log('Deployment ready: https://'+state.url);const domains=await api('/v9/projects/'+project+'/domains');if(!(domains.domains||[]).some(d=>d.name==='nextwork-jobs.vercel.app'))throw Error('Production built, but nextwork-jobs.vercel.app is not assigned to this Vercel project.');console.log('Production URL: https://nextwork-jobs.vercel.app');return}if(['ERROR','CANCELED'].includes(state.readyState))throw Error('Vercel deployment ended in '+state.readyState+'. Check the Vercel build logs.');await new Promise(resolve=>setTimeout(resolve,10000))}throw Error('Vercel deployment is still pending. Check project deployments.');
}
main().catch(error=>{console.error(error.message);process.exit(1)});
